CREATE DATABASE IF NOT EXISTS cinema_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cinema_system;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(30) UNIQUE NULL, user_code VARCHAR(50) UNIQUE NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('CUSTOMER','STAFF','ADMIN') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS genres (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS movies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL UNIQUE, duration_minutes INT NOT NULL, age_rating VARCHAR(20), synopsis TEXT, keywords VARCHAR(500), metadata_json JSON, status VARCHAR(30) NOT NULL DEFAULT 'COMING_SOON', release_date DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS movie_genres (movie_id BIGINT UNSIGNED NOT NULL, genre_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(movie_id,genre_id), FOREIGN KEY(movie_id) REFERENCES movies(id), FOREIGN KEY(genre_id) REFERENCES genres(id));
CREATE TABLE IF NOT EXISTS screening_rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, row_count INT NOT NULL, column_count INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS seats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_id BIGINT UNSIGNED NOT NULL, row_label VARCHAR(5) NOT NULL, seat_number INT NOT NULL, seat_type ENUM('STANDARD','VIP','COUPLE') NOT NULL, UNIQUE(room_id,row_label,seat_number), FOREIGN KEY(room_id) REFERENCES screening_rooms(id));
CREATE TABLE IF NOT EXISTS screenings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT UNSIGNED NOT NULL, room_id BIGINT UNSIGNED NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, UNIQUE(room_id,start_time), FOREIGN KEY(movie_id) REFERENCES movies(id), FOREIGN KEY(room_id) REFERENCES screening_rooms(id));
CREATE TABLE IF NOT EXISTS pricing_rules (seat_type ENUM('STANDARD','VIP','COUPLE') PRIMARY KEY, price DECIMAL(12,2) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO pricing_rules(seat_type,price) VALUES ('STANDARD',80000),('VIP',110000),('COUPLE',160000);
CREATE TABLE IF NOT EXISTS movie_pricing_rules (movie_id BIGINT UNSIGNED NOT NULL, seat_type ENUM('STANDARD','VIP','COUPLE') NOT NULL, price DECIMAL(12,2) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(movie_id,seat_type), FOREIGN KEY(movie_id) REFERENCES movies(id));
CREATE TABLE IF NOT EXISTS seat_holds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, screening_id BIGINT UNSIGNED NOT NULL, seat_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, group_code VARCHAR(100), UNIQUE(screening_id,seat_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(screening_id) REFERENCES screenings(id), FOREIGN KEY(seat_id) REFERENCES seats(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id VARCHAR(100) NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, payment_method VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, transaction_code VARCHAR(160) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_code VARCHAR(100), user_id BIGINT UNSIGNED NOT NULL, screening_id BIGINT UNSIGNED NOT NULL, seat_id BIGINT UNSIGNED NOT NULL, price DECIMAL(12,2), amount DECIMAL(12,2), qr_code VARCHAR(255) UNIQUE, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, checked_in_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(screening_id) REFERENCES screenings(id), FOREIGN KEY(seat_id) REFERENCES seats(id), INDEX(booking_code));
CREATE TABLE IF NOT EXISTS counter_sales (booking_code VARCHAR(100) PRIMARY KEY, customer_name VARCHAR(150) NOT NULL, customer_phone VARCHAR(30), staff_id BIGINT UNSIGNED NOT NULL, FOREIGN KEY(staff_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS refund_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_code VARCHAR(100) UNIQUE NOT NULL, booking_code VARCHAR(100) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, reason TEXT, status VARCHAR(20) DEFAULT 'PENDING', reviewed_by BIGINT UNSIGNED, reviewed_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saved_cards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, cardholder_name VARCHAR(150) NOT NULL, brand VARCHAR(30) NOT NULL, last4 CHAR(4) NOT NULL, token VARCHAR(255) UNIQUE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_contents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT UNSIGNED NULL, content_type VARCHAR(50) NOT NULL, source_text TEXT NOT NULL, generated_text TEXT NOT NULL, status VARCHAR(20) DEFAULT 'DRAFT', generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_by BIGINT UNSIGNED, reviewed_at DATETIME, draft_title VARCHAR(255), draft_genre VARCHAR(100), draft_duration_minutes INT, draft_age_rating VARCHAR(20), draft_keywords VARCHAR(500), draft_release_date DATE, draft_status VARCHAR(30), draft_metadata_json JSON);